import {
  EDITOR_ONLY_DRAFT_EXAMPLE_GROUP_TITLE,
  EDITOR_ONLY_DRAFT_EXAMPLES,
} from './editor-only-draft-examples.ts';
import { getRegisteredPluginDraftExamples } from './editor-plugin-registry.ts';
import {
  EDITOR_ONLY_SHELL_MODE,
  FULL_EDITOR_SHELL_MODE,
  getEditorShellMode,
} from './page-config.ts';

const KNOWN_EDITOR_SHELL_MODES = new Set([
  EDITOR_ONLY_SHELL_MODE,
  FULL_EDITOR_SHELL_MODE,
]);

const DRAFT_EXAMPLES = EDITOR_ONLY_DRAFT_EXAMPLES;

const DRAFT_EXAMPLES_BY_ID = new Map(
  DRAFT_EXAMPLES.map((example) => [example.id, example]),
);

function normalizeDraftExampleEditorShellModes(shellModesValue) {
  if (shellModesValue == null) {
    return [];
  }

  const shellModes = Array.isArray(shellModesValue)
    ? shellModesValue
    : [shellModesValue];

  return Array.from(
    new Set(
      shellModes
        .map((shellMode) =>
          String(shellMode ?? '')
            .trim()
            .toLowerCase(),
        )
        .filter((shellMode) => KNOWN_EDITOR_SHELL_MODES.has(shellMode)),
    ),
  );
}

function isDraftExampleVisibleForShell(
  example,
  shellMode = getEditorShellMode(),
) {
  const editorShellModes = normalizeDraftExampleEditorShellModes(
    example?.editorShellModes,
  );

  return !editorShellModes.length || editorShellModes.includes(shellMode);
}

function getBuiltInDraftExamples(shellMode = getEditorShellMode()) {
  return DRAFT_EXAMPLES.filter((example) => {
    return isDraftExampleVisibleForShell(example, shellMode);
  }).map((example) => ({
    ...example,
    groupTitle:
      typeof example?.groupTitle === 'string' && example.groupTitle.trim()
        ? example.groupTitle.trim()
        : EDITOR_ONLY_DRAFT_EXAMPLE_GROUP_TITLE,
  }));
}

function getDraftExamples() {
  const shellMode = getEditorShellMode();

  return getRegisteredPluginDraftExamples()
    .filter((example) => {
      return isDraftExampleVisibleForShell(example, shellMode);
    })
    .concat(getBuiltInDraftExamples(shellMode));
}

function getDraftExampleById(exampleId) {
  const normalizedExampleId = String(exampleId ?? '');
  const shellMode = getEditorShellMode();

  if (DRAFT_EXAMPLES_BY_ID.has(normalizedExampleId)) {
    const draftExample = DRAFT_EXAMPLES_BY_ID.get(normalizedExampleId) || null;

    return isDraftExampleVisibleForShell(draftExample, shellMode)
      ? draftExample
      : null;
  }

  return (
    getRegisteredPluginDraftExamples().find((example) => {
      return (
        example.id === normalizedExampleId &&
        isDraftExampleVisibleForShell(example, shellMode)
      );
    }) || null
  );
}

export { DRAFT_EXAMPLES, getDraftExampleById, getDraftExamples };
